using UnityEngine;

public class PiezaMovement : MonoBehaviour
{
    public float movementSpeed = 5.0f;
    public bool isDraggable = true;

    private Vector2 startPosition;
    private Vector2 endPosition;

    void Update()
    {
        if (isDraggable)
        {
            if (Input.touchCount > 0)
            {
                Touch touch = Input.touches[0];
                if (touch.phase == TouchPhase.Began)
                {
                    startPosition = touch.position;
                }
                else if (touch.phase == TouchPhase.Moved)
                {
                    endPosition = touch.position;
                    DraggableMovement();
                }
                else if (touch.phase == TouchPhase.Ended)
                {
                    isDraggable = false;
                }
            }
        }
    }

    void DraggableMovement()
    {
        // Calcular la distancia entre la posición inicial y final
        float distance = CalculateDistance(startPosition, endPosition);

        // Mover la pieza
        float movement = distance * movementSpeed * Time.deltaTime;
        transform.position = Vector2.Lerp(startPosition, endPosition, movement);
    }

    float CalculateDistance(Vector2 start, Vector2 end)
    {
        return Vector2.Distance(start, end);
    }
}
